    /// A font family. `faces` maps a weight (400, 500, 600, 700) to the PostScript name of a bundled
    /// face (brand/fonts, SIL OFL 1.1); empty for the system font. `fallbackMonospaced` picks the
    /// system design (SF Mono or SF Pro) used when no face is registered.
    public struct FontFamily: Sendable, Hashable {
        public let name: String, faces: [Int: String], files: [String], fallbackMonospaced: Bool

        /// The bundled face for a weight: the exact weight, else the nearest heavier, else the heaviest.
        public func face(weight: Int) -> String? {
            let weights = faces.keys.sorted()
            guard let pick = weights.first(where: { $0 >= weight }) ?? weights.last else { return nil }
            return faces[pick]
        }
    }

    /// The four families: SF Pro text (SF Compact on watchOS), Instrument Sans titles, JetBrains Mono numbers, Bitcount Single hero numerals.
    public enum Fonts {
        /// Text: SF Pro, the system font — Dynamic Type, Bold Text and SF Symbols weight-matching for free. Nothing to bundle. watchOS sub-brands swap in SF Compact.
        public static let sans = FontFamily(name: "SF Pro Text", faces: [:], files: [], fallbackMonospaced: false)
        /// Titles only: Instrument Sans (SIL OFL 1.1). Its build has no ± or µ, so a title never carries a value — numbers go in mono.
        public static let display = FontFamily(name: "Instrument Sans", faces: [600: "InstrumentSans-SemiBold", 700: "InstrumentSans-Bold"], files: ["InstrumentSans-SemiBold.ttf", "InstrumentSans-Bold.ttf"], fallbackMonospaced: false)
        /// Every number and value: JetBrains Mono (SIL OFL 1.1) — dotted zero (never confused with O or Ø), tabular, 0.55 x-height. SF Mono is the fallback only. Turn off the `calt` ligatures in expression and code fields.
        public static let mono = FontFamily(name: "JetBrains Mono", faces: [400: "JetBrainsMono-Regular", 500: "JetBrainsMono-Medium", 600: "JetBrainsMono-SemiBold"], files: ["JetBrainsMono-Regular.ttf", "JetBrainsMono-Medium.ttf", "JetBrainsMono-SemiBold.ttf"], fallbackMonospaced: true)
        /// Hero numerals only: Bitcount Single (SIL OFL 1.1), a round-dot matrix face — a summary figure, a big readout, a pairing code, marketing. One per screen at most; never body text or inline values. Covers 0–9 . , − ± ° Ø × µ and m.
        public static let hero = FontFamily(name: "Bitcount Single", faces: [400: "BitcountSingle-Regular"], files: ["BitcountSingle-Variable.ttf"], fallbackMonospaced: true)
        /// Every bundled font file, for the app target and Info.plist `UIAppFonts` (files in brand/fonts).
        public static let bundledFiles: [String] = [sans.files, display.files, mono.files, hero.files].flatMap { $0 }
    }

