    /// A motion with its Reduce Motion variant. Control points are a cubic Bézier.
    public struct Motion: Sendable, Hashable {
        public let duration: Double, reducedDuration: Double
        public let c1x: Double, c1y: Double, c2x: Double, c2y: Double
        public func duration(reduceMotion: Bool) -> Double { reduceMotion ? reducedDuration : duration }
    }

    public enum Motions {
        /// Bottom sheet present/dismiss and detent changes.
        public static let sheet = Motion(duration: 0.25, reducedDuration: 0.15, c1x: 0.2, c1y: 0, c2x: 0, c2y: 1)
        /// Selection highlight grow-in.
        public static let selection = Motion(duration: 0.1, reducedDuration: 0, c1x: 0.2, c1y: 0, c2x: 0, c2y: 1)
        /// Something snapping into place (a point to a guide, a card to a slot).
        public static let snap = Motion(duration: 0.1, reducedDuration: 0, c1x: 0, c1y: 0, c2x: 0, c2y: 1)
        /// Toast / error banner in and out.
        public static let toast = Motion(duration: 0.2, reducedDuration: 0.15, c1x: 0, c1y: 0, c2x: 0, c2y: 1)
        /// Animated 3D or map view changes (standard views, zoom to fit).
        public static let camera = Motion(duration: 0.35, reducedDuration: 0, c1x: 0.2, c1y: 0, c2x: 0, c2y: 1)
    }

