    public enum Elevation {
        /// Flat: cards, rows, banners. No shadow — use border.subtle.
        public static let level1 = Shadow(color: RGBA(0x00, 0x00, 0x00, 0x00), x: 0, y: 0, blur: 0, spread: 0)
        /// Floating over the canvas: toolbars, HUD panels, sheets.
        public static let level2 = Shadow(color: RGBA(0x00, 0x00, 0x00, 0x29), x: 0, y: 4, blur: 12, spread: 0)
    }

    public struct Haptic: Sendable, Hashable {
        public enum Generator: String, Sendable { case impact, notification, selection }
        public let generator: Generator, style: String
    }

    public enum Haptics {
        /// Something snaps into place (a point to a guide, a slider to a detent).
        public static let snap = Haptic(generator: .impact, style: "light")
        /// An action is applied (a value set, a command sent).
        public static let confirm = Haptic(generator: .impact, style: "medium")
        /// A task or check completes.
        public static let complete = Haptic(generator: .notification, style: "success")
        /// A soft threshold is reached (a target value, a step in a sequence).
        public static let reached = Haptic(generator: .impact, style: "soft")
        /// Something is about to go wrong.
        public static let warning = Haptic(generator: .notification, style: "warning")
        /// Something failed.
        public static let error = Haptic(generator: .notification, style: "error")
        /// Segmented control / picker detent.
        public static let selectionChanged = Haptic(generator: .selection, style: "default")
    }
}

