public extension Color {
    /// A colour that follows light/dark and Increase Contrast.
    init(btMode c: BTTokens.ModeColor) {
        #if os(watchOS)
        // watchOS is always dark (and true black behind everything): the dark value.
        let v = c.dark
        self.init(.sRGB, red: Double(v.red) / 255, green: Double(v.green) / 255, blue: Double(v.blue) / 255, opacity: Double(v.alpha) / 255)
        #elseif canImport(UIKit)
        self.init(uiColor: UIColor { traits in
            let v = c.resolve(dark: traits.userInterfaceStyle == .dark, highContrast: traits.accessibilityContrast == .high)
            return UIColor(red: CGFloat(v.red) / 255, green: CGFloat(v.green) / 255, blue: CGFloat(v.blue) / 255, alpha: CGFloat(v.alpha) / 255)
        })
        #elseif canImport(AppKit)
        self.init(nsColor: NSColor(name: nil) { appearance in
            let match = appearance.bestMatch(from: [.aqua, .darkAqua, .accessibilityHighContrastAqua, .accessibilityHighContrastDarkAqua])
            let isDark = match == .darkAqua || match == .accessibilityHighContrastDarkAqua
            let isHC = match == .accessibilityHighContrastAqua || match == .accessibilityHighContrastDarkAqua
            let v = c.resolve(dark: isDark, highContrast: isHC)
            return NSColor(srgbRed: CGFloat(v.red) / 255, green: CGFloat(v.green) / 255, blue: CGFloat(v.blue) / 255, alpha: CGFloat(v.alpha) / 255)
        })
        #else
        let v = c.dark
        self.init(.sRGB, red: Double(v.red) / 255, green: Double(v.green) / 255, blue: Double(v.blue) / 255, opacity: Double(v.alpha) / 255)
        #endif
    }

    /// App background behind everything. True black on OLED in dark mode (neutral/100); warm paper in light.
    static let btSurfaceBase = Color(btMode: BTTokens.Colors.surfaceBase)
    /// The working canvas — a model, a map, a photo, a game board. True black in dark mode, so the content is the brightest thing on screen.
    static let btSurfaceCanvas = Color(btMode: BTTokens.Colors.surfaceCanvas)
    /// Sheets, cards, lists and banners — the one raised layer. Flat: separated by border.subtle, not by shadow.
    static let btSurfaceRaised = Color(btMode: BTTokens.Colors.surfaceRaised)
    /// Controls, floating panels, fields and chips. Dark elevation builds up from black: 100 → 90 → 80.
    static let btSurfaceControl = Color(btMode: BTTokens.Colors.surfaceControl)
    /// Dimming layer under modal sheets (64 % black). Decorative; not a contrast pair.
    static let btSurfaceScrim = Color(btMode: BTTokens.Colors.surfaceScrim)
    /// Body text, labels, values.
    static let btTextPrimary = Color(btMode: BTTokens.Colors.textPrimary)
    /// Supporting text, units, captions.
    static let btTextSecondary = Color(btMode: BTTokens.Colors.textSecondary)
    /// Placeholder and hint text. Still AA on every surface.
    static let btTextTertiary = Color(btMode: BTTokens.Colors.textTertiary)
    /// Disabled labels. Exempt from WCAG contrast; always paired with a disabled shape/state.
    static let btTextDisabled = Color(btMode: BTTokens.Colors.textDisabled)
    /// Dividers, card and banner outlines. Decorative (no contrast requirement); flat surfaces separate with this instead of shadow.
    static let btBorderSubtle = Color(btMode: BTTokens.Colors.borderSubtle)
    /// Field outlines and control boundaries that identify a control — 3:1 non-text contrast.
    static let btBorderStrong = Color(btMode: BTTokens.Colors.borderStrong)
    /// The accent, strictly: the active control, a selected chip or segment, a toggle that is on. Never decoration, links, headings, brand marks or a primary button.
    static let btAccentFill = Color(btMode: BTTokens.Colors.accentFill)
    /// Pressed state of an accent fill.
    static let btAccentFillPressed = Color(btMode: BTTokens.Colors.accentFillPressed)
    /// Label/icon on an accent fill (dark text on amber).
    static let btAccentOn = Color(btMode: BTTokens.Colors.accentOn)
    /// The accent as text or an icon on a surface: the label of the active control or selected segment only. Links are neutral (underlined).
    static let btAccentText = Color(btMode: BTTokens.Colors.accentText)
    /// Keyboard / Full Keyboard Access focus ring (2 px, offset 2 px).
    static let btAccentFocus = Color(btMode: BTTokens.Colors.accentFocus)
    /// Primary button fill (Beatham convention: neutral/20 fill, neutral/80 label in dark). Neutral, so the accent never competes with it.
    static let btActionPrimaryFill = Color(btMode: BTTokens.Colors.actionPrimaryFill)
    /// Primary button label.
    static let btActionPrimaryLabel = Color(btMode: BTTokens.Colors.actionPrimaryLabel)
    /// Secondary button fill.
