public extension BTTokens {
    /// True when a font with this PostScript name is registered (bundled under UIAppFonts or
    /// registered with CTFontManager). Font.custom silently falls back to SF Pro when it is not,
    /// which would lose the monospaced fallback — so Font(btStyle:) checks first.
    static func isFontRegistered(_ postScriptName: String) -> Bool {
        #if canImport(UIKit)
        return UIFont(name: postScriptName, size: 12) != nil
        #elseif canImport(AppKit)
        return NSFont(name: postScriptName, size: 12) != nil
        #else
        return false
        #endif
    }
}

public extension Font {
    /// A Dynamic Type font from a token style (scales with the user's text size). Bundled faces go
    /// through Font.custom(_:size:relativeTo:); if the face isn't registered, the SF fallback is used
    /// (SF Mono for mono and hero, SF Pro otherwise). Pass `boldText` from
    /// `@Environment(\.legibilityWeight) == .bold`: system fonts embolden themselves, bundled faces
    /// step up to the next heavier face (+200).
    init(btStyle s: BTTokens.TextStyle, boldText: Bool = false) {
        let style: Font.TextStyle
        switch s.textStyle {
        case "largeTitle": style = .largeTitle
        case "title": style = .title
        case "title2": style = .title2
        case "title3": style = .title3
        case "headline": style = .headline
        case "body": style = .body
        case "callout": style = .callout
        case "subheadline": style = .subheadline
        case "footnote": style = .footnote
        case "caption": style = .caption
        case "caption2": style = .caption2
        default: style = .body
        }
        let weight: Font.Weight
        switch s.weight {
        case 400: weight = .regular
        case 500: weight = .medium
        case 600: weight = .semibold
        case 700: weight = .bold
        default: weight = .regular
        }
        if let face = s.family.face(weight: s.weight + (boldText ? 200 : 0)), BTTokens.isFontRegistered(face) {
            self = Font.custom(face, size: s.size, relativeTo: style)
            return
        }
        let design: Font.Design = s.family.fallbackMonospaced || s.monospaced ? .monospaced : .default
        let font = Font.system(style, design: design, weight: weight)
        self = s.monospaced ? font.monospacedDigit() : font
    }

    // Computed, not stored: the registration check runs on each use, so fonts registered at launch
    // with CTFontManager are picked up even if a token font was read before registration.
    /// The largest title on a screen. Instrument Sans — titles never carry values.
    static var btLargeTitle: Font { Font(btStyle: BTTokens.Typography.largeTitle) }

    static var btTitle1: Font { Font(btStyle: BTTokens.Typography.title1) }
    /// Sheet titles.
    static var btTitle2: Font { Font(btStyle: BTTokens.Typography.title2) }

    static var btTitle3: Font { Font(btStyle: BTTokens.Typography.title3) }
    /// Section headers, row titles.
    static var btHeadline: Font { Font(btStyle: BTTokens.Typography.headline) }
    /// Default text.
    static var btBody: Font { Font(btStyle: BTTokens.Typography.body) }

    static var btCallout: Font { Font(btStyle: BTTokens.Typography.callout) }
    /// Field labels, supporting rows.
    static var btSubheadline: Font { Font(btStyle: BTTokens.Typography.subheadline) }

    static var btFootnote: Font { Font(btStyle: BTTokens.Typography.footnote) }
    /// Toolbar labels.
    static var btCaption1: Font { Font(btStyle: BTTokens.Typography.caption1) }
    /// Smallest allowed; badges only.
    static var btCaption2: Font { Font(btStyle: BTTokens.Typography.caption2) }
    /// Numeric and expression fields (JetBrains Mono, tabular; calt off).
    static var btNumericField: Font { Font(btStyle: BTTokens.Typography.numericField) }
    /// Units, counts, coordinates, codes (JetBrains Mono).
    static var btNumericCaption: Font { Font(btStyle: BTTokens.Typography.numericCaption) }
    /// Hero numerals (Bitcount Single, dot matrix): a summary figure, a big readout, a pairing code, marketing. One number per screen at most; never body text or inline values.
    static var btHeroNumeral: Font { Font(btStyle: BTTokens.Typography.heroNumeral) }
}

public extension Animation {
    /// A token motion; pass `@Environment(\.accessibilityReduceMotion)`.
    static func bt(_ m: BTTokens.Motion, reduceMotion: Bool) -> Animation {
        .timingCurve(m.c1x, m.c1y, m.c2x, m.c2y, duration: m.duration(reduceMotion: reduceMotion))
    }
    static func btSheet(reduceMotion: Bool) -> Animation { bt(BTTokens.Motions.sheet, reduceMotion: reduceMotion) }
    static func btSelection(reduceMotion: Bool) -> Animation { bt(BTTokens.Motions.selection, reduceMotion: reduceMotion) }
    static func btSnap(reduceMotion: Bool) -> Animation { bt(BTTokens.Motions.snap, reduceMotion: reduceMotion) }
    static func btToast(reduceMotion: Bool) -> Animation { bt(BTTokens.Motions.toast, reduceMotion: reduceMotion) }
    static func btCamera(reduceMotion: Bool) -> Animation { bt(BTTokens.Motions.camera, reduceMotion: reduceMotion) }
}

