/// When to play a haptic. Never the only feedback — each has a visual change too.
public enum BTHaptic: CaseIterable, Sendable {
    case snap, confirm, complete, reached, warning, error, selectionChanged

    public var token: BTTokens.Haptic {
        switch self {
        case .snap: BTTokens.Haptics.snap
        case .confirm: BTTokens.Haptics.confirm
        case .complete: BTTokens.Haptics.complete
        case .reached: BTTokens.Haptics.reached
        case .warning: BTTokens.Haptics.warning
        case .error: BTTokens.Haptics.error
        case .selectionChanged: BTTokens.Haptics.selectionChanged
        }
    }
}

#if canImport(UIKit) && !os(watchOS) && !os(tvOS)
import UIKit

public extension BTHaptic {
    @MainActor func play() {
        let t = token
        switch t.generator {
        case .impact:
            let style: UIImpactFeedbackGenerator.FeedbackStyle
            switch t.style {
            case "light": style = .light
            case "heavy": style = .heavy
            case "soft": style = .soft
            case "rigid": style = .rigid
            default: style = .medium
            }
            UIImpactFeedbackGenerator(style: style).impactOccurred()
        case .notification:
            let type: UINotificationFeedbackGenerator.FeedbackType
            switch t.style {
            case "success": type = .success
            case "warning": type = .warning
            default: type = .error
            }
            UINotificationFeedbackGenerator().notificationOccurred(type)
        case .selection:
            UISelectionFeedbackGenerator().selectionChanged()
        }
    }
}
#elseif os(watchOS)
import WatchKit

public extension BTHaptic {
    /// The nearest WKHapticType: impacts and selection click, notifications map to success / retry / failure.
    @MainActor func play() {
        let t = token
        let type: WKHapticType
        switch (t.generator, t.style) {
        case (.notification, "success"): type = .success
        case (.notification, "warning"): type = .retry
        case (.notification, _): type = .failure
        case (.impact, "heavy"), (.impact, "rigid"): type = .start
        default: type = .click
        }
        WKInterfaceDevice.current().play(type)
    }
}
#endif
